--
-- Table structure for table `combo_entradas`
--

DROP TABLE IF EXISTS `combo_entradas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `combo_entradas` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `combo_id` bigint unsigned NOT NULL,
  `tipo` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `combo_grupo_id` bigint unsigned DEFAULT NULL,
  `grupo_complemento_id` bigint unsigned DEFAULT NULL,
  `referencia_id` bigint unsigned DEFAULT NULL,
  `nome_snapshot` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `preco_snapshot` decimal(10,2) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `combo_entradas_combo_id_foreign` (`combo_id`),
  KEY `combo_entradas_combo_grupo_id_foreign` (`combo_grupo_id`),
  KEY `combo_entradas_grupo_complemento_id_foreign` (`grupo_complemento_id`),
  CONSTRAINT `combo_entradas_combo_grupo_id_foreign` FOREIGN KEY (`combo_grupo_id`) REFERENCES `combo_grupos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `combo_entradas_combo_id_foreign` FOREIGN KEY (`combo_id`) REFERENCES `itens` (`id`) ON DELETE CASCADE,
  CONSTRAINT `combo_entradas_grupo_complemento_id_foreign` FOREIGN KEY (`grupo_complemento_id`) REFERENCES `grupo_complemento` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

