DROP TABLE IF EXISTS `geocoding_caches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `geocoding_caches` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `endereco_formatado` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `endereco_formatado_google` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `hash_endereco` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `latitude` decimal(10,8) NOT NULL,
  `longitude` decimal(11,8) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `geocoding_caches_hash_endereco_unique` (`hash_endereco`),
  KEY `geocoding_caches_hash_endereco_index` (`hash_endereco`)
) ENGINE=InnoDB AUTO_INCREMENT=240 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

