-- Table structure for table `pedido_itens`
--

DROP TABLE IF EXISTS `pedido_itens`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pedido_itens` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `pedido_id` bigint unsigned NOT NULL,
  `item_id` bigint unsigned DEFAULT NULL,
  `external_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `uuid` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tamanho_id` bigint unsigned DEFAULT NULL,
  `borda_id` bigint unsigned DEFAULT NULL,
  `preco_borda` double DEFAULT '0',
  `massa_id` bigint unsigned DEFAULT NULL,
  `preco_massa` double DEFAULT '0',
  `nome` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `quantidade` int NOT NULL,
  `preco_unitario` double NOT NULL,
  `subtotal` double DEFAULT NULL,
  `tipo` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tipo_preco` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `observacao` text COLLATE utf8mb4_unicode_ci,
  `item_premio` tinyint(1) NOT NULL DEFAULT '0',
  `preco_original` decimal(10,2) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `pedido_itens_pedido_id_foreign` (`pedido_id`),
  KEY `pedido_itens_item_id_foreign` (`item_id`),
  KEY `pedido_itens_borda_id_foreign` (`borda_id`),
  KEY `pedido_itens_massa_id_foreign` (`massa_id`),
  KEY `pedido_itens_tamanho_id_foreign` (`tamanho_id`),
  CONSTRAINT `pedido_itens_borda_id_foreign` FOREIGN KEY (`borda_id`) REFERENCES `categoria_borda` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pedido_itens_item_id_foreign` FOREIGN KEY (`item_id`) REFERENCES `itens` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pedido_itens_massa_id_foreign` FOREIGN KEY (`massa_id`) REFERENCES `categoria_massa` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pedido_itens_pedido_id_foreign` FOREIGN KEY (`pedido_id`) REFERENCES `pedidos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pedido_itens_tamanho_id_foreign` FOREIGN KEY (`tamanho_id`) REFERENCES `categoria_tamanho` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1174 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
