CREATE TABLE `pedidos` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ifood_display_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pedido_ifood_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ifood_entregue_por` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `endereco_entrega_ifood` bigint unsigned DEFAULT NULL,
  `mesa` int DEFAULT NULL,
  `comanda` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `informa_comanda_manual` tinyint(1) NOT NULL DEFAULT '0',
  `empresa_id` bigint unsigned DEFAULT NULL,
  `cliente_id` bigint unsigned DEFAULT NULL,
  `tipo` varchar(1) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pendente',
  `prioridade` tinyint(1) NOT NULL DEFAULT '0',
  `eh_agendado` tinyint(1) NOT NULL DEFAULT '0',
  `observacao` text COLLATE utf8mb4_unicode_ci,
  `codigo_coleta` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `valor_frete` double DEFAULT NULL,
  `endereco_entrega_id` bigint unsigned DEFAULT NULL,
  `fidelidade_recompensa_aplicada` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fidelidade_desconto` decimal(10,2) NOT NULL DEFAULT '0.00',
  `fidelidade_percentual` decimal(5,2) DEFAULT NULL,
  `fidelidade_base_calculo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `frete_original` decimal(10,2) DEFAULT NULL,
  `nome` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `telefone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cpf_cnpj_ifood` varchar(14) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `data_agendamento_inicio` datetime DEFAULT NULL,
  `data_agendamento_fim` datetime DEFAULT NULL,
  `data_inicio_preparo` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `pedidos_cliente_id_foreign` (`cliente_id`),
  KEY `pedidos_pedido_ifood_id_index` (`pedido_ifood_id`),
  KEY `pedidos_endereco_entrega_ifood_foreign` (`endereco_entrega_ifood`),
  KEY `pedidos_empresa_id_status_created_at_index` (`empresa_id`,`status`,`created_at`),
  KEY `pedidos_endereco_entrega_id_foreign` (`endereco_entrega_id`),
  CONSTRAINT `pedidos_cliente_id_foreign` FOREIGN KEY (`cliente_id`) REFERENCES `clientes` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `pedidos_empresa_id_foreign` FOREIGN KEY (`empresa_id`) REFERENCES `empresas` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pedidos_endereco_entrega_id_foreign` FOREIGN KEY (`endereco_entrega_id`) REFERENCES `enderecos` (`id`),
  CONSTRAINT `pedidos_endereco_entrega_ifood_foreign` FOREIGN KEY (`endereco_entrega_ifood`) REFERENCES `enderecos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1764 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
